#!/bin/bash
# Kotlin Autocomplete Lookup Helper
# Queries the autocomplete metadata generated by kotlin-autocomplete-gradle-plugin
# Usage: kotlin-autocomplete-lookup.sh <fully.qualified.TypeName> [autocomplete-dir]

set -e

TYPE=$1
AUTOCOMPLETE_DIR=${2:-"build/autocomplete"}

if [ -z "$TYPE" ]; then
    echo "Usage: $0 <fully.qualified.TypeName> [autocomplete-dir]"
    echo ""
    echo "Example: $0 kotlin.String"
    echo "         $0 com.example.User ./build/autocomplete"
    exit 1
fi

if [ ! -d "$AUTOCOMPLETE_DIR" ]; then
    echo "Error: Autocomplete metadata not found at: $AUTOCOMPLETE_DIR"
    echo ""
    echo "To generate autocomplete metadata:"
    echo "  ./gradlew buildAutocomplete"
    echo ""
    echo "Make sure the kotlin-autocomplete plugin is applied in build.gradle.kts:"
    echo "  plugins {"
    echo "    id(\"com.lightningkite.kotlin-autocomplete\") version \"0.0.1-1\""
    echo "  }"
    exit 1
fi

INDEX_FILE="$AUTOCOMPLETE_DIR/index.json"

if [ ! -f "$INDEX_FILE" ]; then
    echo "Error: index.json not found at: $INDEX_FILE"
    exit 1
fi

# Look up which file contains this type
FILE=$(jq -r --arg type "$TYPE" '.[$type] // empty' "$INDEX_FILE")

if [ -z "$FILE" ]; then
    echo "Type not found: $TYPE"
    echo ""
    echo "Available types (first 20):"
    jq -r 'keys[]' "$INDEX_FILE" | head -20
    echo "..."
    echo ""
    TOTAL=$(jq 'keys | length' "$INDEX_FILE")
    echo "Total types indexed: $TOTAL"
    exit 1
fi

# Read the type's metadata
TYPE_FILE="$AUTOCOMPLETE_DIR/$FILE"

if [ ! -f "$TYPE_FILE" ]; then
    echo "Error: Metadata file not found: $TYPE_FILE"
    exit 1
fi

echo "=== Type: $TYPE ==="
echo "File: $FILE"
echo ""

# Extract and format the data
MEMBERS=$(jq -r --arg type "$TYPE" '.[$type].members[]' "$TYPE_FILE" 2>/dev/null || echo "")
EXTENSIONS=$(jq -r --arg type "$TYPE" '.[$type].extensions[]' "$TYPE_FILE" 2>/dev/null || echo "")

if [ -n "$MEMBERS" ]; then
    echo "Members:"
    echo "$MEMBERS" | while read -r line; do
        echo "  - $line"
    done
else
    echo "Members: (none)"
fi

echo ""

if [ -n "$EXTENSIONS" ]; then
    echo "Extensions:"
    echo "$EXTENSIONS" | while read -r line; do
        echo "  - $line"
    done
else
    echo "Extensions: (none)"
fi

# Count statistics
MEMBER_COUNT=$(echo "$MEMBERS" | grep -c . || echo 0)
EXTENSION_COUNT=$(echo "$EXTENSIONS" | grep -c . || echo 0)

echo ""
echo "Total: $MEMBER_COUNT members, $EXTENSION_COUNT extensions"
